{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name IN ('SELECT ts.trip2','SELECT Trip','Transaction.commit') GROUP BY ALL",
          "claim": "Travel2 DB spans (SELECT ts.trip2, SELECT Trip, Transaction.commit) have p50 of 1.8s to 3.8s in the abnormal window"
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM normal_traces WHERE service_name='ts-travel2-service' AND span_name IN ('SELECT ts.trip2','SELECT Trip','Transaction.commit') GROUP BY ALL",
          "claim": "In the normal window the same travel2 DB spans have p50 under 1 ms"
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, round(avg(\"value\"),3) v FROM abnormal_metrics WHERE service_name='ts-travel2-service' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY ALL",
          "claim": "Travel2 container CPU and memory stay flat (CPU usage about 0.06), so the slowdown is not resource saturation"
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Client' AND span_name='POST' GROUP BY ALL",
          "claim": "Route-plan's client POST calls to travel2 slow to p95 of about 14 s, versus about 112 ms in normal"
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "Travel-plan server spans rise to p50 of 15-19 s, while travel-plan's own time stays small"
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "User-facing dashboard requests reach p95 of about 7 s in the abnormal window, against about 170 ms normally"
        }
      ]
    }
  ]
}

